from pathlib import Path
import argparse, csv, gzip, hashlib, json
from collections import defaultdict
import numpy as np, pandas as pd
from sklearn.decomposition import PCA

ROOT=Path(__file__).resolve().parents[2]

def sha(p):
 h=hashlib.sha256()
 with open(p,"rb") as f:
  for b in iter(lambda:f.read(1<<20),b""):h.update(b)
 return h.hexdigest()

def build(raw,output):
 raw=Path(raw); files={x:raw/f"GSE337988_sublib2_de_matrices_lfc_matrix_{x}.csv.gz" for x in ("Low1","Low2","Med","High")}; types=defaultdict(lambda:"float32"); types["gene"]="string"; matrices={x:pd.read_csv(p,dtype=types).set_index("gene") for x,p in files.items()}; first=matrices["Low1"]; assert all(first.index.equals(x.index) and first.columns.equals(x.columns) for x in matrices.values()); guide=list(csv.DictReader(gzip.open(raw/"GSE337988_NGS6475_crispr_demux_index_map_prod.csv.gz","rt"))); condition_gene={r["sample"]+"_"+r["promoter"]:r["sample"].upper() for r in guide}; genes=np.asarray([condition_gene[x] for x in first.columns]); meta=pd.read_csv(ROOT/"data/feng2024/data/preprocessed_data/meta_table_9845.csv"); ids={str(s).upper():int(i) for s,i in zip(meta.symbol,meta.unified_id)}; held=set(json.loads((ROOT/"results/sl_predict/slkb_outcomes_intervention_external.json").read_text())["symbols"]); val=lambda x:int.from_bytes(hashlib.sha256(x.encode()).digest()[:4],"big")%5==0; keep=np.asarray([x!="NTC" and x in ids and x not in held for x in genes]); role=np.asarray([1 if val(x) else 0 for x in genes[keep]],"int8"); gene=np.asarray([ids[x] for x in genes[keep]],"int16"); condition=first.columns.to_numpy()[keep]; low1=matrices["Low1"].to_numpy().T[keep]; low2=matrices["Low2"].to_numpy().T[keep]; med=matrices["Med"].to_numpy().T[keep]; high=matrices["High"].to_numpy().T[keep]; assert all(np.isfinite(x).all() for x in (low1,low2,med,high)); low=.5*(low1+low2); train=role==0; pool=np.concatenate((low[train],med[train],high[train])); center=pool.mean(0); scale=pool.std(0).clip(.01); normalized=(pool-center)/scale; pca=PCA(64,svd_solver="randomized",random_state=731).fit(normalized); latent_scale=pca.transform(normalized).std(0).clip(.05); project=lambda x:(pca.transform((x-center)/scale)/latent_scale).astype("float32"); low_target,med_target,high_target=project(low),project(med),project(high); replicate=float(np.corrcoef(low1.ravel(),low2.ravel())[0,1]); per_condition=np.asarray([np.corrcoef(a,b)[0,1] for a,b in zip(low1,low2)]); noise=float(np.sqrt(np.mean((low1-low2)**2))); contrast=float(np.sqrt(np.mean((high-low)**2))); out=Path(output); out.parent.mkdir(parents=True,exist_ok=True); np.savez_compressed(out,gene=gene,role=role,condition=condition,target_gene=genes[keep],response_gene=first.index.to_numpy(),target_low=low_target,target_med=med_target,target_high=high_target,pca_mean=pca.mean_.astype("float32"),pca_components=pca.components_.astype("float32"),feature_center=center.astype("float32"),feature_scale=scale.astype("float32"),target_scale=latent_scale.astype("float32")); audit={"schema":"sl-predict-gse337988-moi-state-v1","input_sha256":{x:sha(p) for x,p in files.items()},"matrix_shape":[*first.shape],"conditions":len(first.columns),"response_genes":len(first.index),"usable_conditions":len(gene),"usable_unique_genes":int(len(np.unique(gene))),"train_conditions":int(train.sum()),"validation_conditions":int((~train).sum()),"low_replicate_global_correlation":replicate,"low_replicate_median_condition_correlation":float(np.nanmedian(per_condition)),"low_replicate_rms_disagreement":noise,"high_minus_low_rms":contrast,"contrast_to_noise":contrast/noise,"state_dimensions":64,"explained_variance":float(pca.explained_variance_ratio_.sum()),"benchmark_membership_used_for_exclusion_only":True,"outcome_files_read":False,"sl_labels_used":False}; out.with_suffix(".json").write_text(json.dumps(audit,indent=2)); print(json.dumps(audit,indent=2))

if __name__=="__main__":
 p=argparse.ArgumentParser(); p.add_argument("--raw",default=ROOT/"data/perturbseq_sources/gse337988_audit"); p.add_argument("--output",default=ROOT/"results/sl_predict/gse337988_moi_state.npz"); a=p.parse_args(); build(a.raw,a.output)
